#!/usr/bin/env python3
"""Avenra Stage 6A hosted-demo implementation updater, version 20261025.

Backs up source and preserves databases, private keys, accounts and unrelated work.
Does not deploy or modify hosted data. Live setup and physical acceptance are
separate explicit commands; no security certification or real-data pilot claim.
"""
import argparse
import base64
import difflib
import gzip
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile
import time

PAYLOAD = ''
BASE = 'da68fc1'


def run(command, root, env=None, capture=False):
    result=subprocess.run(command,cwd=root,env=env,text=True,stdout=subprocess.PIPE if capture else None,stderr=subprocess.PIPE if capture else None)
    if result.returncode:
        detail=('\n'+result.stderr.strip()) if capture and command[:2]==['git','show'] else ''
        raise RuntimeError('Command failed: '+' '.join(command[:4])+detail)
    return result.stdout.strip() if capture else None


def normal(text):return ''.join(text.split())


def strip_functions(text,names):
    """Recognise only the previously reviewed in-progress diary functions."""
    pattern=re.compile(r'(?m)^[ \t]*function\s+('+ '|'.join(map(re.escape,names)) +r')\s*\(')
    spans=[]
    for match in pattern.finditer(text):
        start=text.find('{',match.end())
        if start<0:raise RuntimeError('Malformed diary function')
        depth=0;quote=None;line_comment=False;block_comment=False;escape=False;i=start
        while i<len(text):
            c=text[i];n=text[i+1] if i+1<len(text) else ''
            if line_comment:
                if c=='\n':line_comment=False
            elif block_comment:
                if c=='*' and n=='/':block_comment=False;i+=1
            elif quote:
                if escape:escape=False
                elif c=='\\':escape=True
                elif c==quote:quote=None
            elif c in ("'",'"','`'):quote=c
            elif c=='/' and n=='/':line_comment=True;i+=1
            elif c=='/' and n=='*':block_comment=True;i+=1
            elif c=='{':depth+=1
            elif c=='}':
                depth-=1
                if depth==0:
                    spans.append((match.start(),i+1));break
            i+=1
        else:raise RuntimeError('Unbalanced diary function')
    for start,end in reversed(spans):text=text[:start]+text[end:]
    return normal(text)


def compatible_local(name,current,baseline):
    if name=='static/survivor/diary.js':
        names={'queueItem','queueNewEntry','removeQueuedItem','blockDiaryUpload','uploadSingleEntry','uploadOwnedEntry','saveEntry'}
        return strip_functions(current,names)==strip_functions(baseline,names)
    if name=='static/survivor/queue.js':
        current=current.replace('captureOwner: captureOwner,','').replace('refreshOwner: refreshOwner,','')
        return normal(current)==normal(baseline)
    if name=='static/survivor/diary.html':
        current=current.replace('<script src="/survivor/queue.js" defer></script>','')
        return normal(current)==normal(baseline)
    if name=='static/survivor/service-worker.js':
        return normal(re.sub(r'clear-sky-shell-v\d+','clear-sky-shell-V',current))==normal(re.sub(r'clear-sky-shell-v\d+','clear-sky-shell-V',baseline))
    if name=='tests/stage5_pwa_browser.py':
        current=re.sub(r'(?m)^\s*offline_tab\.evaluate\([^\n]*CWQueue\.ready[^\n]*\)\s*\n','',current)
        return normal(current)==normal(baseline)
    return False


def plan(root,files):
    run(['git','merge-base','--is-ancestor',BASE,'HEAD'],root)
    if run(['git','branch','--show-current'],root,capture=True)!='main':raise RuntimeError('Run on main; no branch switch was attempted')
    if subprocess.run(['git','diff','--cached','--quiet'],cwd=root).returncode:raise RuntimeError('Existing staged changes found; no files written')
    if run(['git','diff','--name-only','--diff-filter=U'],root,capture=True):raise RuntimeError('Resolve the existing merge first; no files written')
    pending=[]
    for name,entry in files.items():
        target=root/name
        if target.is_symlink() or not target.resolve().is_relative_to(root):raise RuntimeError('Unexpected file location: '+name)
        raw=base64.b64decode(entry['data'])
        if hashlib.sha256(raw).hexdigest()!=entry['sha256']:raise RuntimeError('Package integrity error: '+name)
        current=target.read_bytes() if target.is_file() else None
        if current==raw:continue
        expected=entry['before']
        current_hash=hashlib.sha256(current).hexdigest() if current is not None else None
        if current_hash!=expected:
            approved=False
            if current is not None and expected is not None:
                old=subprocess.run(['git','show',BASE+':'+name],cwd=root,capture_output=True)
                if old.returncode==0:
                    try:approved=compatible_local(name,current.decode(),old.stdout.decode())
                    except (UnicodeError,RuntimeError):approved=False
            elif name=='tests/hosted_diary_queue_browser.py' and current is not None:
                approved=(b'Synthetic diary queue ownership tests' in current and b'CWDiary' in current)
            if not approved:raise RuntimeError('Unreviewed changes in '+name+'. Nothing written. Share git status and that file diff; do not overwrite it.')
        pending.append((name,target,raw))
    modified=run(['git','diff','--name-only'],root,capture=True).splitlines()
    unexpected=[name for name in modified if name not in files and name!='tools/stage6_finish.py']
    if unexpected:raise RuntimeError('Unrelated tracked edits found: '+', '.join(unexpected))
    return pending


def apply(root,files):
    pending=plan(root,files)
    self_target=root/'tools/stage6_finish.py'
    own=Path(__file__).resolve().read_bytes()
    if self_target.exists() and self_target.resolve()!=Path(__file__).resolve() and self_target.read_bytes()!=own:
        raise RuntimeError('An existing tools/stage6_finish.py differs; no files written')
    backup=Path(tempfile.mkdtemp(prefix='avenra-stage6-source-backup-'));backup.chmod(0o700)
    for name,target,raw in pending+[('tools/stage6_finish.py',self_target,own)]:
        if target.is_file() and target.read_bytes()==raw:continue
        if target.exists():
            saved=backup/name;saved.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,saved);saved.chmod(0o600)
        target.parent.mkdir(parents=True,exist_ok=True)
        descriptor,temp=tempfile.mkstemp(prefix='.avenra-stage6-',dir=target.parent)
        try:
            with os.fdopen(descriptor,'wb') as stream:stream.write(raw)
            os.chmod(temp,0o644);os.replace(temp,target)
        finally:
            if os.path.exists(temp):os.unlink(temp)
        print('Updated:',name,flush=True)
    print('Source backup:',backup)
    print('No database, credentials, account, hosted environment or deployment changed.',flush=True)


def verify(root,files):
    for name,entry in files.items():
        if not (root/name).is_file() or hashlib.sha256((root/name).read_bytes()).hexdigest()!=entry['sha256']:
            raise RuntimeError('Source differs from the reviewed delivery: '+name)
    candidate=root/'.venv/bin/python'
    python=str(candidate) if candidate.is_file() else sys.executable
    env=os.environ.copy()
    for key in list(env):
        if key in {'DATABASE_URL','PUBLIC_BASE_URL','VERCEL','VERCEL_ENV','DEVICE_TOKEN','SMS_WEBHOOK_URL','TELEGRAM_BOT_TOKEN','TELEGRAM_CHAT_ID'} or key.startswith(('SMTP_','WEBPUSH_','TWILIO_')):
            env.pop(key,None)
    env.update(APP_ENV='development',COOKIE_SECURE='0',SECRET_KEY='stage6-synthetic-test-key-never-deploy-0123456789',AVENRA_SMS_ENABLED='0',AVENRA_WEBPUSH_ENABLED='0',AVENRA_PUSH_SELF_TEST='0')
    env.pop('DIARY_STORAGE_BACKEND',None)
    env['AVENRA_SERVER_PYTHON']=python
    scripts=['hosted_diary_queue_browser.py','hosted_alert_queue_browser.py','hosted_pwa_pairing_browser.py',
             'staff_invitation_browser.py','stage1_dashboard_browser.py','stage2_pwa_browser.py',
             'stage3_case_browser.py','stage4_audit_browser.py','stage4_pwa_browser.py',
             'stage5_pwa_browser.py','webpush_browser.py']
    commands=[[python,'-m','unittest','discover','-s','tests','-p','test_*.py','-v']]
    commands += [[python,'tests/'+name] for name in scripts]
    commands += [['node','tests/service-worker-contract.cjs'],['node','tests/pwa-shell.cjs'],[python,'tools/check_stage0.py']]
    for name in sorted((root/'static/survivor').glob('*.js')):commands.append(['node','--check',str(name)])
    commands += [['node','--check','static/js/devices.js'],['git','diff','--check']]
    for command in commands:
        print('\nCHECK: '+' '.join(command),flush=True)
        run(command,root,env=env)
    for name,entry in files.items():
        if hashlib.sha256((root/name).read_bytes()).hexdigest()!=entry['sha256']:
            raise RuntimeError('Source changed during verification: '+name)
    directory=Path.home()/'.local/share/avenra-hosted';directory.mkdir(parents=True,exist_ok=True,mode=0o700)
    report={'release':'stage6-demo-20261025','local_automated_checks':True,'hosted_verified':False,'phone_verified':False,'pilot_ready':False,'files':{name:entry['sha256'] for name,entry in files.items()}}
    target=directory/'stage6-local-check.json'
    descriptor=os.open(target,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o600)
    with os.fdopen(descriptor,'w') as stream:json.dump(report,stream,indent=2)
    print('PASS: local automated release checks. Hosted setup and physical phone acceptance remain pending.',flush=True)


def commit(root,files):
    run(['git','fetch','origin'],root)
    run(['git','merge-base','--is-ancestor','origin/main','HEAD'],root)
    if subprocess.run(['git','diff','--cached','--quiet'],cwd=root).returncode:raise RuntimeError('Other staged changes exist; nothing committed')
    paths=sorted(files)+['tools/stage6_finish.py']
    run(['git','add','--']+paths,root)
    run(['git','diff','--cached','--check'],root)
    if subprocess.run(['git','diff','--cached','--quiet'],cwd=root).returncode:
        staged=run(['git','diff','--cached','--no-ext-diff'],root,capture=True)
        if ('-----BEGIN '+'PRIVATE KEY-----') in staged:raise RuntimeError('Possible private key in staged diff; commit refused')
        run(['git','commit','-m','Complete Stage 6 hosted-demo engineering and acceptance tooling'],root)
    print('Commit:',run(['git','rev-parse','--short','HEAD'],root,capture=True))


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo',type=Path,default=Path.cwd())
    for flag in ('apply','verify','commit','push'):parser.add_argument('--'+flag,action='store_true')
    args=parser.parse_args()
    root=args.repo.resolve()
    if not (root/'avenra/application.py').is_file():raise RuntimeError('Run from the Avenra repository or supply --repo')
    files=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    if args.commit and run(['git','branch','--show-current'],root,capture=True)!='main':raise RuntimeError('Commit/push must run on main')
    if args.commit and not args.verify:raise RuntimeError('--commit requires --verify in the same invocation')
    if args.push and not (args.commit and args.verify):raise RuntimeError('--push requires --verify --commit')
    if args.apply:apply(root,files)
    elif not args.verify:
        pending=plan(root,files)
        print('REVIEW:',len(pending),'source files would change. Known in-progress diary edits are backed up and reconciled.')
        for name,_,_ in pending:print(name)
        print('Use --apply --verify --commit --push to install, verify and publish source. This does not deploy.')
        return
    if args.verify:verify(root,files)
    if args.commit:commit(root,files)
    if args.push:
        run(['git','push','origin','HEAD:main'],root)
        print('PASS: verified source pushed to main. No deploy command was run.')
    print('NEXT: source the private hosted runtime; run tools/stage6_hosted.py --prepare, deploy, verify, schedule, then complete physical phone acceptance.')

if __name__=='__main__':
    try:main()
    except Exception as error:
        print('STOP:',str(error),file=sys.stderr)
        print('Do not deploy or mark Stage 6 complete. No database reset or force-push was attempted.',file=sys.stderr)
        raise SystemExit(1)
